import pandas as pd
import numpy as np


def character_count_table(elements, include_index=False):
    elements_series = pd.Series(elements, dtype=object)
    count_series = elements_series.apply(len)
    data = {'Element': elements_series, 'Count': count_series}
    if include_index:
        data['Index'] = np.arange(len(elements))
    df = pd.DataFrame(data)
    if include_index:
        df = df[['Index', 'Element', 'Count']]
    rows = []
    for row in df.itertuples(index=False, name=None):
        rows.append(tuple(v.item() if hasattr(v, 'item') else v for v in row))
    return rows

import re
import numpy as np
from scipy.stats import ttest_rel


def paired_ttest_word_lengths(text1, text2):
    lens1 = np.array([len(w) for w in re.split(r'\W+', text1) if w])
    lens2 = np.array([len(w) for w in re.split(r'\W+', text2) if w])
    if len(lens1) != len(lens2) or len(lens1) < 2:
        return None
    diffs = lens1 - lens2
    if np.all(diffs == diffs[0]):
        return None
    t_stat, p_val = ttest_rel(lens1, lens2)
    return (float(t_stat), float(p_val))

