from datetime import date

def _second_friday(year, month):
    wd = date(year, month, 1).weekday()
    return date(year, month, 1 + (4 - wd) % 7 + 7)

def second_friday_price_series(start_date, prices):
    start = date.fromisoformat(start_date)
    year, month = start.year, start.month
    result = []
    i = 0
    while i < len(prices):
        d = _second_friday(year, month)
        if d >= start:
            result.append((d.isoformat(), float(prices[i])))
            i += 1
        month += 1
        if month > 12:
            month = 1
            year += 1
    return result

