from html.parser import HTMLParser


class _TableParser(HTMLParser):
    def __init__(self, table_id):
        super().__init__()
        self.table_id = table_id
        self.found = False
        self.depth = 0
        self.rows = []
        self.cur_row = None
        self.cur_cell = None

    def handle_starttag(self, tag, attrs):
        if tag == 'table':
            if self.depth:
                self.depth += 1
            elif not self.found and dict(attrs).get('id') == self.table_id:
                self.found = True
                self.depth = 1
        elif self.depth == 1:
            if tag == 'tr':
                self.cur_row = []
            elif tag in ('td', 'th') and self.cur_row is not None:
                self.cur_cell = []

    def handle_endtag(self, tag):
        if tag == 'table':
            if self.depth:
                self.depth -= 1
        elif self.depth == 1:
            if tag in ('td', 'th') and self.cur_cell is not None:
                self.cur_row.append(''.join(self.cur_cell).strip())
                self.cur_cell = None
            elif tag == 'tr' and self.cur_row is not None:
                self.rows.append(self.cur_row)
                self.cur_row = None

    def handle_data(self, data):
        if self.cur_cell is not None:
            self.cur_cell.append(data)


def _convert_column(values):
    try:
        return [int(v) for v in values]
    except ValueError:
        pass
    try:
        return [float(v) for v in values]
    except ValueError:
        return list(values)


def table_rows_by_id(html, table_id):
    parser = _TableParser(table_id)
    parser.feed(html)
    parser.close()
    if not parser.found:
        raise ValueError('Table with the specified ID not found.')
    if not parser.rows:
        return []
    header = parser.rows[0]
    data = parser.rows[1:]
    if not data:
        return [header]
    columns = [_convert_column([row[i] for row in data]) for i in range(len(header))]
    converted = [list(r) for r in zip(*columns)]
    return [header] + converted

