import numpy as np
from statsmodels.regression.linear_model import OLS


def fit_linear_regression(rows):
    if not rows or any(len(r) != 5 for r in rows):
        raise ValueError("Each row must have exactly 5 elements.")
    data = np.asarray(rows, dtype=float)
    X = np.column_stack([np.ones(len(data)), data[:, :4]])
    y = data[:, 4]
    results = OLS(y, X).fit()
    return [float(v) for v in results.params], float(results.rsquared)

