import math
from collections import Counter


def _chi2_sf(x, k):
    y = x / 2.0
    if k % 2 == 0:
        term = 1.0
        total = 1.0
        for i in range(1, k // 2):
            term *= y / i
            total += term
        result = math.exp(-y) * total
    else:
        result = math.erfc(math.sqrt(y))
        if y > 0:
            term = math.sqrt(y) * math.exp(-y) / math.gamma(1.5)
            for i in range(1, (k - 1) // 2 + 1):
                if i > 1:
                    term *= y / (i - 0.5)
                result += term
    return min(1.0, max(0.0, result))


def _is_numeric(col):
    return len(col) > 0 and all(isinstance(v, (int, float)) and not isinstance(v, bool) for v in col)


def chi_square_independence_pvalue(data, col1, col2):
    if not data or all(len(v) == 0 for v in data.values()):
        raise ValueError("The input data is empty.")
    if col1 not in data or col2 not in data:
        raise ValueError("Column not found.")
    a, b = list(data[col1]), list(data[col2])
    if _is_numeric(a) or _is_numeric(b):
        raise TypeError("Columns must contain categorical data.")
    rows = list(dict.fromkeys(a))
    cols = list(dict.fromkeys(b))
    if len(rows) < 2 or len(cols) < 2:
        raise ValueError("Each column needs at least two categories.")
    counts = Counter(zip(a, b))
    table = [[counts[(r, c)] for c in cols] for r in rows]
    if any(cell < 5 for row in table for cell in row):
        raise ValueError("Some cells have fewer than 5 observations.")
    n = sum(sum(row) for row in table)
    row_tot = [sum(row) for row in table]
    col_tot = [sum(table[i][j] for i in range(len(rows))) for j in range(len(cols))]
    dof = (len(rows) - 1) * (len(cols) - 1)
    chi2 = 0.0
    for i in range(len(rows)):
        for j in range(len(cols)):
            e = row_tot[i] * col_tot[j] / n
            o = float(table[i][j])
            if dof == 1:
                d = e - o
                if d != 0:
                    o += math.copysign(min(0.5, abs(d)), d)
            chi2 += (o - e) ** 2 / e
    return float(_chi2_sf(chi2, dof))

