from pandas.api.types import is_numeric_dtype, is_bool_dtype
from scipy.stats import chi2_contingency


def _numeric(s):
    return is_numeric_dtype(s) and not is_bool_dtype(s)


def chi_square_independence_pvalue(data, col1, col2):
    df = pd.DataFrame(data)
    if df.empty:
        raise ValueError("The input data is empty.")
    if col1 not in df or col2 not in df:
        raise ValueError("Column not found.")
    if _numeric(df[col1]) or _numeric(df[col2]):
        raise TypeError("Columns must contain categorical data.")
    if df[col1].nunique() < 2 or df[col2].nunique() < 2:
        raise ValueError("Each column needs at least two categories.")
    table = pd.crosstab(df[col1], df[col2])
    if (table < 5).any().any():
        raise ValueError("Some cells have fewer than 5 observations.")
    _, p, _, _ = chi2_contingency(table.to_numpy())
    return float(p)

